     EnsureTestApplication();var dir=Path.Combine(Output,"r3");Directory.CreateDirectory(dir);using var cms=new LcmsRgbEngine();var source=Fixture(dir,"input",cms.StandardProfile("DisplayP3"));using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs(dir));await vm.LoadTargetAsync(source);await vm.CreateManagedColorVariantAsync();vm.Editor.SetToolParameter(ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.BasicTone).Single(p=>p.Key=="exposure"),.4);await vm.RawLocalPreviewWork;var basis=vm.ActiveTarget!.ActiveEditVersionId;var count=vm.ActiveTarget.EditVersions.Count;
     vm.EnableLightPrintWorkspace();vm.InstantCameraAnimation=false;vm.InstantInputMode="CurrentEdits";vm.InstantV3Seed=123456;vm.SelectedPhotographerPaperId="blue-duochrome600";await vm.LightPrintPreviewWork;Assert.AreEqual(count,vm.ActiveTarget.EditVersions.Count,"draft must not add variant");
     vm.CancelLightPrintPreviewCommand.Execute(null);Assert.AreEqual(basis,vm.ActiveTarget.ActiveEditVersionId);vm.InstantInputMode="CurrentEdits";await vm.DevelopLightPrintCommand.ExecuteAsync(null);Assert.IsTrue(vm.IsLightPrintLocked,vm.LightPrintStatus+" / "+vm.StatusText);var developed=vm.ActiveTarget.ActiveEditVersionId;var definition=vm.ActiveTarget.RawDefinition!;Assert.IsNotNull(definition.InstantInput?.ColorDocument);Assert.AreEqual(basis,definition.InstantInput.OriginVersionId);var recipe=JsonSerializer.Serialize(definition);vm.InstantV3Seed=987654;vm.SelectedLightPrintFrameId="generic.white.circle";Assert.AreEqual(recipe,JsonSerializer.Serialize(vm.ActiveTarget.RawDefinition));Assert.IsFalse(vm.RerollLightPrintPreviewCommand.CanExecute(null));await vm.DevelopLightPrintCommand.ExecuteAsync(null);Assert.AreEqual(developed,vm.ActiveTarget.ActiveEditVersionId,"repeat click must not create half variants");
     var session=Path.Combine(dir,"r3.ptstudio.json");await vm.SaveSessionAsync(session);using var reopen=new ReferenceColorWorkspaceViewModel(new Dialogs(dir));await reopen.LoadSessionAsync(session);Assert.AreEqual(recipe,JsonSerializer.Serialize(reopen.ActiveTarget!.RawDefinition));
     vm.ReshootLightPrintCommand.Execute(null);await vm.LightPrintPreviewWork;Assert.IsFalse(vm.IsLightPrintLocked);Assert.AreEqual(developed,vm.ActiveTarget.ActiveEditVersionId);await vm.DevelopLightPrintCommand.ExecuteAsync(null);Assert.AreNotEqual(developed,vm.ActiveTarget.ActiveEditVersionId,vm.StatusText);Assert.AreEqual("Original",vm.ActiveTarget.RawDefinition?.InstantInput?.Mode);Assert.IsNull(vm.ActiveTarget.RawDefinition?.InstantInput?.ColorDocument?.LocalEdits);Assert.IsTrue(vm.ActiveTarget.EditVersions.Any(v=>v.Id==developed));
     await File.WriteAllTextAsync(Path.Combine(dir,"RESULT.json"),JsonSerializer.Serialize(new{basis,developed,reshoot=vm.ActiveTarget.ActiveEditVersionId,animation=false,recipeFrozen=true,originalInput=true,currentEditsInput=true,repeatClickSafe=true,scope="Product VM/WPF workflow, not native mouse"}));
    });
    [TestMethod] public Task ExportUsesFrozenManagedVariantAcrossSwitchAndDisposal() => RunSta(async()=>
    {
     EnsureTestApplication();var dir=Path.Combine(Output,"switch-export");Directory.CreateDirectory(dir);using var cms=new LcmsRgbEngine();var srgb=cms.StandardProfile("sRGB");using var image=new HighBitDepthImageBuffer(300,200,Enumerable.Repeat(.3f,300*200*3).ToArray());var d=InstantFilmJpegInput.Definition with{RenderedInputVersion=2,ColorState=new(srgb,srgb,cms.StandardProfile("DisplayP3"))};var m=Master(image,d,new string('a',64));var path=Path.Combine(dir,"frozen.jpg");bool changed=false;var current=d;var result=await DocumentColorWorkflowV1.WriteAsync(m,d,path,StudioExportFormat.Jpeg,CancellationToken.None,stage=>{if(stage=="RenderRow"&&!changed){changed=true;current=current with{ColorState=current.ColorState! with{Output=cms.StandardProfile("AdobeRGB")}};}});Assert.AreNotEqual(d.ColorState.Output.Sha256,current.ColorState!.Output.Sha256);Assert.IsTrue(result.EncoderConfiguration.EndsWith(d.ColorState.Output.Sha256));Assert.AreEqual(8,result.BitDepth);Assert.IsFalse(result.PixelComparisonPerformed);DocumentColorWorkflowV1.Inspect(path,m,d,StudioExportFormat.Jpeg);
     using var cancel=new CancellationTokenSource();var stopped=Path.Combine(dir,"close.jpg");await Assert.ThrowsAsync<OperationCanceledException>(async()=>await DocumentColorWorkflowV1.WriteAsync(m,d,stopped,StudioExportFormat.Jpeg,cancel.Token,s=>{if(s=="RenderRow")cancel.Cancel();}));Assert.IsFalse(File.Exists(stopped));Assert.HasCount(0,Directory.GetFiles(dir,"*.cms-*"));
    });

